/**
 * Turns a clean catalogue scan into something that looks like a card cropped out of a phone
 * photo of a binder page: tilted, loosely cropped, glared, sleeved, blurred and compressed.
 * Everything is driven by a seeded RNG so a test set can be regenerated byte-for-byte.
 */
import sharp from 'sharp'

export type Rng = () => number

/** mulberry32 — small, fast, good enough for test data. */
export function makeRng(seed: number): Rng {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const between = (rng: Rng, lo: number, hi: number) => lo + (hi - lo) * rng()
const pick = <T>(rng: Rng, items: readonly T[]) => items[Math.floor(rng() * items.length)]

function gaussian(rng: Rng) {
  const u = Math.max(rng(), 1e-9)
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rng())
}

export type Severity = 'mild' | 'medium' | 'harsh'
export const SEVERITIES: readonly Severity[] = ['mild', 'medium', 'harsh']

export type DamageKind =
  | 'tilt'
  | 'loose-crop'
  | 'glare'
  | 'sleeve'
  | 'exposure'
  | 'blur'
  | 'motion-blur'
  | 'noise'
  | 'low-res'
  | 'jpeg'

export type DamageRecord = {
  severity: Severity
  applied: DamageKind[]
  params: Record<string, number | string>
}

const STRENGTH: Record<Severity, number> = { mild: 0.35, medium: 0.7, harsh: 1 }

// How often each optional effect shows up; low-res + JPEG always apply (every phone crop has them)
const CHANCE: Record<Exclude<DamageKind, 'loose-crop' | 'low-res' | 'jpeg'>, number> = {
  tilt: 0.7,
  glare: 0.45,
  sleeve: 0.4,
  exposure: 0.6,
  blur: 0.35,
  'motion-blur': 0.2,
  noise: 0.45,
}

// What sits behind a card in a binder pocket or on a table
const BACKGROUNDS: ReadonlyArray<[number, number, number]> = [
  [18, 18, 22], // black binder page
  [28, 34, 58], // navy binder
  [70, 20, 24], // red binder
  [205, 200, 190], // white table
  [120, 84, 52], // wood
  [90, 94, 100], // grey mat
]

type Point = [number, number]
type Raw = { data: Buffer; width: number; height: number }

/** Solve for the 3×3 homography taking `from[i]` → `to[i]` (four point pairs). */
function homography(from: Point[], to: Point[]): number[] {
  const A: number[][] = []
  for (let i = 0; i < 4; i++) {
    const [x, y] = from[i]
    const [u, v] = to[i]
    A.push([x, y, 1, 0, 0, 0, -u * x, -u * y, u])
    A.push([0, 0, 0, x, y, 1, -v * x, -v * y, v])
  }
  // Gauss-Jordan with partial pivoting on the 8×9 augmented matrix
  for (let c = 0; c < 8; c++) {
    let p = c
    for (let r = c + 1; r < 8; r++) if (Math.abs(A[r][c]) > Math.abs(A[p][c])) p = r
    ;[A[c], A[p]] = [A[p], A[c]]
    for (let r = 0; r < 8; r++) {
      if (r === c) continue
      const f = A[r][c] / A[c][c]
      for (let k = c; k < 9; k++) A[r][k] -= f * A[c][k]
    }
  }
  return [...A.map((row, i) => row[8] / row[i]), 1]
}

/**
 * Place the card on a background with a perspective tilt, then crop the way a card detector
 * would: the quad's bounding box with some slack (or a bit cut off) on each side.
 */
function placeCard(card: Raw, rng: Rng, s: number, record: DamageRecord): Raw {
  const { width: w, height: h } = card
  const tilt = rng() < CHANCE.tilt
  const corners: Point[] = [
    [0, 0],
    [w, 0],
    [w, h],
    [0, h],
  ]
  let quad: Point[] = corners.map(([x, y]) => [x, y])
  if (tilt) {
    const angle = (between(rng, -7, 7) * s * Math.PI) / 180
    const jitter = 0.07 * s * w
    const cx = w / 2
    const cy = h / 2
    quad = corners.map(([x, y]) => {
      const dx = x - cx
      const dy = y - cy
      return [
        cx + dx * Math.cos(angle) - dy * Math.sin(angle) + between(rng, -jitter, jitter),
        cy + dx * Math.sin(angle) + dy * Math.cos(angle) + between(rng, -jitter, jitter),
      ]
    })
    record.applied.push('tilt')
    record.params.tiltDeg = +((angle * 180) / Math.PI).toFixed(1)
  }

  // Detector boxes are never exact: slack on each side, occasionally a sliver cut off
  const margins = [0, 1, 2, 3].map(() => between(rng, -0.025 * s, 0.1 * s) * w)
  if (margins.some((m) => Math.abs(m) > 0.01 * w)) record.applied.push('loose-crop')
  record.params.cropMargins = margins.map((m) => (m / w).toFixed(3)).join(',')

  const xs = quad.map((p) => p[0])
  const ys = quad.map((p) => p[1])
  const left = Math.min(...xs) - margins[3]
  const top = Math.min(...ys) - margins[0]
  const outW = Math.max(16, Math.round(Math.max(...xs) + margins[1] - left))
  const outH = Math.max(16, Math.round(Math.max(...ys) + margins[2] - top))

  // Inverse map: output pixel → card pixel
  const H = homography(
    quad.map(([x, y]) => [x - left, y - top]),
    corners,
  )
  const bg = pick(rng, BACKGROUNDS)
  record.params.background = bg.join(',')
  const out = Buffer.alloc(outW * outH * 3)
  const src = card.data
  for (let y = 0; y < outH; y++) {
    const shade = 0.85 + 0.3 * (y / outH)
    for (let x = 0; x < outW; x++) {
      const d = H[6] * x + H[7] * y + H[8]
      const u = (H[0] * x + H[1] * y + H[2]) / d
      const v = (H[3] * x + H[4] * y + H[5]) / d
      const o = (y * outW + x) * 3
      let r = bg[0] * shade
      let g = bg[1] * shade
      let b = bg[2] * shade
      if (u >= 0 && v >= 0 && u < w - 1 && v < h - 1) {
        const x0 = u | 0
        const y0 = v | 0
        const fx = u - x0
        const fy = v - y0
        const i00 = (y0 * w + x0) * 4
        const i10 = i00 + 4
        const i01 = i00 + w * 4
        const i11 = i01 + 4
        const lerp = (c: number) =>
          (src[i00 + c] * (1 - fx) + src[i10 + c] * fx) * (1 - fy) +
          (src[i01 + c] * (1 - fx) + src[i11 + c] * fx) * fy
        // Alpha keeps the rounded card corners showing the background
        const a = lerp(3) / 255
        r = r * (1 - a) + lerp(0) * a
        g = g * (1 - a) + lerp(1) * a
        b = b * (1 - a) + lerp(2) * a
      }
      out[o] = r
      out[o + 1] = g
      out[o + 2] = b
    }
  }
  return { data: out, width: outW, height: outH }
}

/** Per-pixel lighting: exposure / white balance, glare hotspots, sleeve sheen, sensor noise. */
function light(img: Raw, rng: Rng, s: number, record: DamageRecord) {
  const { data, width: w, height: h } = img
  const exposure = rng() < CHANCE.exposure
  const gain = exposure ? between(rng, 1 - 0.35 * s, 1 + 0.25 * s) : 1
  const wb = [0, 1, 2].map(() => (exposure ? 1 + between(rng, -0.12, 0.12) * s : 1))
  const contrast = exposure ? between(rng, 1 - 0.3 * s, 1 + 0.15 * s) : 1
  if (exposure) {
    record.applied.push('exposure')
    record.params.gain = +gain.toFixed(2)
    record.params.contrast = +contrast.toFixed(2)
  }

  const spots: Array<{ x: number; y: number; rx: number; ry: number; k: number }> = []
  if (rng() < CHANCE.glare) {
    const n = rng() < 0.3 ? 2 : 1
    for (let i = 0; i < n; i++) {
      spots.push({
        x: between(rng, 0.1, 0.9) * w,
        y: between(rng, 0.05, 0.95) * h,
        rx: between(rng, 0.1, 0.35) * w,
        ry: between(rng, 0.06, 0.25) * h,
        k: between(rng, 0.5, 0.95) * s,
      })
    }
    record.applied.push('glare')
    record.params.glareSpots = n
  }

  let band: { nx: number; ny: number; c: number; half: number; k: number; haze: number } | null = null
  if (rng() < CHANCE.sleeve) {
    const angle = between(rng, 0, Math.PI)
    const nx = Math.cos(angle)
    const ny = Math.sin(angle)
    // Projections of the image corners onto the band normal span [lo, hi]
    const lo = Math.min(0, w * nx)
    const hi = Math.max(0, w * nx) + h * ny
    band = {
      nx,
      ny,
      c: lo + between(rng, 0.2, 0.8) * (hi - lo),
      half: between(rng, 0.04, 0.14) * w,
      k: between(rng, 0.2, 0.5) * s,
      haze: between(rng, 0.03, 0.1) * s,
    }
    record.applied.push('sleeve')
  }

  const noise = rng() < CHANCE.noise ? between(rng, 3, 12) * s : 0
  if (noise) {
    record.applied.push('noise')
    record.params.noise = +noise.toFixed(1)
  }

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      // Screen-blend amount of white from glare + sleeve at this pixel
      let white = 0
      for (const g of spots) {
        const d = ((x - g.x) / g.rx) ** 2 + ((y - g.y) / g.ry) ** 2
        if (d < 1) white = 1 - (1 - white) * (1 - g.k * (1 - d) ** 2)
      }
      if (band) {
        const along = Math.abs(x * band.nx + y * band.ny - band.c)
        const inBand = along < band.half ? band.k * (1 - along / band.half) : 0
        white = 1 - (1 - white) * (1 - inBand) * (1 - band.haze)
      }
      const o = (y * w + x) * 3
      for (let c = 0; c < 3; c++) {
        let v = data[o + c] / 255
        v = ((v - 0.5) * contrast + 0.5) * gain * wb[c]
        v = 1 - (1 - v) * (1 - white)
        if (noise) v += (gaussian(rng) * noise) / 255
        data[o + c] = Math.max(0, Math.min(255, v * 255))
      }
    }
  }
}

function motionKernel(length: number, angle: number) {
  const size = length % 2 ? length : length + 1
  const kernel = new Array(size * size).fill(0)
  const c = (size - 1) / 2
  for (let t = -c; t <= c; t += 0.25) {
    const x = Math.round(c + t * Math.cos(angle))
    const y = Math.round(c + t * Math.sin(angle))
    kernel[y * size + x] = 1
  }
  return { width: size, height: size, kernel, scale: kernel.reduce((a, b) => a + b, 0) }
}

/**
 * Damage one card image. `source` is any image sharp can read (the cached catalogue webp).
 * Returns a JPEG the size of a typical crop out of a binder-page photo.
 */
export async function damageCard(
  source: Buffer,
  rng: Rng,
  severity: Severity,
): Promise<{ jpeg: Buffer; record: DamageRecord }> {
  const s = STRENGTH[severity]
  const record: DamageRecord = { severity, applied: [], params: {} }

  const card = await sharp(source).ensureAlpha().raw().toBuffer({ resolveWithObject: true })
  const placed = placeCard({ data: card.data, width: card.info.width, height: card.info.height }, rng, s, record)
  light(placed, rng, s, record)

  let img = sharp(placed.data, { raw: { width: placed.width, height: placed.height, channels: 3 } })
  if (rng() < CHANCE.blur) {
    const sigma = +between(rng, 0.6, 2.4 * s + 0.6).toFixed(2)
    img = sharp(await img.blur(sigma).raw().toBuffer(), {
      raw: { width: placed.width, height: placed.height, channels: 3 },
    })
    record.applied.push('blur')
    record.params.blurSigma = sigma
  }
  if (rng() < CHANCE['motion-blur']) {
    const length = Math.round(between(rng, 3, 3 + 12 * s))
    img = sharp(await img.convolve(motionKernel(length, between(rng, 0, Math.PI))).raw().toBuffer(), {
      raw: { width: placed.width, height: placed.height, channels: 3 },
    })
    record.applied.push('motion-blur')
    record.params.motionPx = length
  }

  // A card cropped from a 9-pocket page photo is only a few hundred pixels wide
  const width = Math.round(between(rng, 520 - 300 * s, 760 - 360 * s))
  const quality = Math.round(between(rng, 88 - 50 * s, 95 - 40 * s))
  record.applied.push('low-res', 'jpeg')
  record.params.width = width
  record.params.jpegQuality = quality
  const jpeg = await img.resize({ width }).jpeg({ quality, mozjpeg: true }).toBuffer()
  return { jpeg, record }
}
